<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, router } from '@inertiajs/vue3';
import { computed, onMounted, onUnmounted, ref } from 'vue';

const props = defineProps({ document: Object });
const copied = ref(false);
let timer;
const data = computed(() => props.document.extracted_json || {});
const json = computed(() => JSON.stringify(data.value, null, 2));
function copyJson() { navigator.clipboard.writeText(json.value); copied.value = true; setTimeout(() => copied.value = false, 1600); }
function exportCsv() { const items = data.value.line_items || []; const rows = [['description', 'quantity', 'price'], ...items.map(item => [item.description, item.quantity, item.price])]; const csv = rows.map(row => row.map(value => `"${String(value ?? '').replaceAll('"', '""')}"`).join(',')).join('\n'); const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv' })); link.download = `${props.document.original_filename}.csv`; link.click(); URL.revokeObjectURL(link.href); }
onMounted(() => { if (props.document.status === 'pending') timer = setInterval(() => router.reload({ only: ['document'] }), 2500); });
onUnmounted(() => clearInterval(timer));
</script>

<template>
    <Head :title="document.original_filename" /><AuthenticatedLayout><div class="min-h-screen bg-[#f4f6f3] text-[#17251d]"><main class="mx-auto max-w-7xl px-5 py-10 sm:px-8"><div class="mb-8 flex flex-wrap items-center justify-between gap-4"><div><Link :href="route('dashboard')" class="text-sm text-[#718078] hover:text-[#18372b]">← Voltar ao workspace</Link><h1 class="mt-4 max-w-xl truncate text-3xl font-semibold">{{ document.original_filename }}</h1></div><div class="flex gap-2"><button @click="exportCsv" :disabled="!document.extracted_json" class="rounded-lg border border-[#ccd8cf] bg-white px-4 py-2.5 text-sm font-semibold disabled:opacity-40">Exportar CSV</button><button @click="copyJson" :disabled="!document.extracted_json" class="rounded-lg bg-[#18372b] px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-40">{{ copied ? 'Copiado' : 'Copiar JSON' }}</button></div></div><div class="grid min-h-[600px] gap-5 lg:grid-cols-[.9fr_1.1fr]"><div class="flex items-center justify-center rounded-2xl border border-[#dce4de] bg-[#dfe5e0] p-6"><iframe v-if="document.original_filename.toLowerCase().endsWith('.pdf')" :src="route('documents.download', document.id)" class="h-full min-h-[560px] w-full rounded-lg bg-white" title="Prévia do documento"></iframe><div v-else class="text-center text-[#718078]"><div class="mb-3 text-5xl">▧</div>Prévia disponível para PDFs<div class="mt-2 text-xs">{{ document.original_filename }}</div></div></div><div class="rounded-2xl border border-[#dce4de] bg-white p-6 sm:p-8"><div class="mb-8 flex items-center justify-between"><div><p class="text-xs font-bold uppercase tracking-[.18em] text-[#9aa79f]">Dados extraídos</p><p class="mt-2 text-sm text-[#718078]">{{ document.status === 'pending' ? 'Analisando seu documento...' : document.status === 'failed' ? 'Não foi possível processar este arquivo.' : 'Revise os campos antes de exportar.' }}</p></div><span class="h-3 w-3 rounded-full" :class="document.status === 'processed' ? 'bg-[#55a66c]' : document.status === 'failed' ? 'bg-[#d97860]' : 'animate-pulse bg-[#d6a84f]'"></span></div><div v-if="document.status === 'processed'" class="grid gap-5 sm:grid-cols-2"><div v-for="field in ['vendor_name', 'invoice_number', 'date', 'total_amount']" :key="field" class="border-b border-[#edf0ed] pb-3"><p class="text-xs capitalize text-[#9aa79f]">{{ field.replaceAll('_', ' ') }}</p><p class="mt-1 font-medium">{{ data[field] ?? 'Não identificado' }}</p></div></div><pre v-if="document.status === 'processed'" class="mt-8 max-h-64 overflow-auto rounded-xl bg-[#f5f7f4] p-4 text-xs leading-6 text-[#52655a]">{{ json }}</pre><div v-else class="flex min-h-56 items-center justify-center rounded-xl bg-[#f5f7f4] text-sm text-[#87958c]">{{ document.status === 'pending' ? 'Aguarde alguns segundos...' : 'Tente enviar o arquivo novamente.' }}</div></div></div></main></div></AuthenticatedLayout>
</template>
